pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        // The owner (default is the test contract) approves alice
        c.setApprovedLogger(alice, true);
        // Now the owner revokes approval: onlyOwner should restrict, but mutation removes the check.
        // In the reference, only the owner can call setApprovedLogger; the test contract is the owner so this should work.
        c.setApprovedLogger(alice, false);
        // In the reference, alice is now NOT an approved logger.
        // But the mutation (always-pass onlyOwner) would have allowed anyone to call setApprovedLogger; however the call above was by the owner, so both contracts set it to false.
        // We need an observable difference: we need a call that the mutation would allow but the reference would not.
        // Actually, the mutation removes the onlyOwner check, but in the scenario where the owner always calls, both contracts behave the same.
        // The difference must be triggered by a call from a non-owner. So let's have a non-owner try to set themselves as approved.
        // But the reference reverts on non-owner, the mutation does not revert.
        // So we do:
        vm.prank(alice);
        // In reference, this reverts because alice is not owner. In mutation, it passes.
        // We use try-catch to capture the revert boolean.
        bool ok;
        try c.setApprovedLogger(alice, true) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, ok = false because revert. In the mutation, ok = true.
        // Now we assert that the reference holds: ok should be false because only owner can set.
        // But the mutation would make ok = true, and then approvedLoggers[alice] would be true despite alice not being owner.
        // However the test must PASS on reference and FAIL on bug. So we assert that ok is false.
        assertTrue(!ok);
    }
}

